pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testRegression_property() public {
        // The constructor sets C's _ownerAddress to address(this), _rankedBattleAddress to address(this), and _fighterFarmInstance to address(this).
        // By default, winnersPerPeriod = 2.
        // We call addPoints(tokenId=0, points=1) via address(this) (the Ranked Battle address).
        // The reference does not change winnersPerPeriod; the buggy version sets it to 0.
        vm.prank(address(this));
