contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testRegression_property() public {
        // Initially winnersPerPeriod = 2, rankedBattleAddress = address(this)
        // Call addPoints as a non-rankedBattle (msg.sender = address(this) which is the rankedBattleAddress via deploy)
        // To avoid the require, we must be the rankedBattleAddress; but the deploy sets it to address(this).
        // So we need to change who calls: use vm.prank with a different address after deploy.
        // First, we need to ensure the caller is NOT the rankedBattleAddress.
        // The buggy version removed the require so any caller can call addPoints.
        // We'll call addPoints from a random address that is not rankedBattleAddress.
        address nonRanked = address(0x1234);
        vm.prank(nonRanked);
        // Call addPoints with value 3 to cause underflow (2 - 3) in buggy version.
        c.addPoints(0, 3);
        // Now winnersPerPeriod: reference reverts so it stays 2, buggy underflows to uint256 max.
        // Check the stored value: c.winnersPerPeriod() should be 2 for reference, huge for bug.
        // Since we cannot know which version we're on, we distinguish by checking if it's > 100 (indicating underflow).
        assertTrue(c.winnersPerPeriod() != 2, "Buggy version should have underflowed away from 2");
    }
