pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testRegression_property() public {
        // The caller is address(this) which is NOT the rankedBattleAddress (set to address(this) in constructor)
        // Actually constructor sets _rankedBattleAddress = address(this), so we need a different caller.
        // Use a different address that is not the ranked battle address.
        address attacker = address(0x1234);
        vm.prank(attacker);
        // Call addPoints with tokenId=0, points=100. The reference requires msg.sender == _rankedBattleAddress (address(this)), so it reverts.
        // The buggy version (with subtraction in updateWinnersPerPeriod) does not have that require and will execute the function body.
        // But addPoints itself still has the require, so it will revert for attacker in both versions.
        // This approach is wrong because addPoints reverts in both.
        // Instead, we need to trigger the bug via updateWinnersPerPeriod which is called by an admin.
        // Let's set up an admin call to updateWinnersPerPeriod with a value that causes underflow in buggy version.
        // The bug is in updateWinnersPerPeriod: it subtracts instead of assigning.
        // So call updateWinnersPerPeriod as admin with a value > current winnersPerPeriod (2) to cause underflow.
        // But reference version would assign, so winnersPerPeriod becomes that value (e.g., 3).
        // Buggy version subtracts: 2 - 3 = underflow to huge number.
        // Admin is address(this) because constructor sets isAdmin[ownerAddress] = true and ownerAddress = address(this).
        vm.prank(address(this));
        c.updateWinnersPerPeriod(3);
        // Now read winnersPerPeriod:
        uint256 wp = c.winnersPerPeriod();
        // Reference: wp == 3. Buggy: wp == type(uint256).max - ? Actually 2 - 3 underflows to 2^256 - 1.
        // So assertion: wp == 3 should pass on reference (true) and fail on buggy (false).
        assertTrue(wp == 3);
    }
}

