pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testRegression_property() public {
        // Deploy a simple ERC721 receiver for fighter minting
        // But we don't need to mint any fighters; the ownerOf call will revert because there are no tokens
        // Instead, ensure the pickWinner call can proceed: we need winners that are existing fighters
        // But we cannot mint fighters without the full setup. So we use a simpler approach:
        // The test will call pickWinner with an empty array (winners.length = 0), which will fail because winnersPerPeriod = 2
        // To make it work, we need to set winnersPerPeriod to 0 and also ensure no token ownership issues
        // Since we cannot easily mint fighters, we can instead change winnersPerPeriod to 0 and pick 0 winners
        // Then the loop is empty and does not call ownerOf
        vm.prank(address(this));
        c.updateWinnersPerPeriod(0);
        // Now pickWinner with 0 winners will pass the length check and loop, then in P roundId becomes 1
        // In M it will revert before increment, so roundId stays 0
        // We must catch the potential revert in M
        bool success;
        bytes memory data = abi.encodeWithSelector(c.pickWinner.selector, new uint256[](0));
        (success, ) = address(c).call(data);
        assertTrue(success == true && c.roundId() == 1);
    }
}

